import 'package:cooknote/src/cooking/ingredient_parser.dart';

/// Một dòng nguyên liệu kèm kết quả tách mong đợi (AC-31). Dòng tự viết kiểu
/// công thức thật, không chép từ trang web.
class IngredientCase {
  const IngredientCase(
    this.line, {
    this.qty,
    this.qtyMax,
    this.unit,
    this.name = '',
    this.note = '',
  });

  /// Dòng không tách được số lượng: giữ nguyên chữ, `structured=false`.
  const IngredientCase.plain(this.line)
    : qty = null,
      qtyMax = null,
      unit = null,
      name = line,
      note = '';

  final String line;
  final double? qty;
  final double? qtyMax;
  final IngredientUnit? unit;
  final String name;
  final String note;

  bool get structured => qty != null;
}

